const listLocationsForTenant = `-- name: ListLocationsForTenant :many
SELECT id, tenant_id, name, static_ips, gps_lat, gps_lng, shift_start, shift_end,
       overnight, created_at, wifi_ssid
FROM locations
WHERE tenant_id = $1
ORDER BY name
`

// GPS fallback path (CLAUDE.md section 5, row 6): when no IP matches, the domain
// computes the haversine distance from the tap's GPS to each location and checks
// the < 150 m radius. Returns every location in the tenant so that check can run.
func (q *Queries) ListLocationsForTenant(ctx context.Context, tenantID uuid.UUID) ([]Location, error) {
	rows, err := q.db.Query(ctx, listLocationsForTenant, tenantID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Location{}
	for rows.Next() {
		var i Location
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Name,
			&i.StaticIps,
			&i.GpsLat,
			&i.GpsLng,
			&i.ShiftStart,
			&i.ShiftEnd,
			&i.Overnight,
			&i.CreatedAt,
			&i.WifiSsid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

